arguments.command:
cat > lib/prune/retention.sh.new <<'EOF'
#!/bin/bash
# Retention for audit logs: 400 days (ADR-0015, docs/adr/0015-audit-log-retention.md:18).
PRUNE_KEEP_DAYS=400
prune_keep_days() { echo "$PRUNE_KEEP_DAYS"; }
prune_find_args() { echo "-type f -mtime +$(( $(prune_keep_days) - 1 ))"; }
EOF
head -2 lib/prune/retention.sh; head -2 lib/prune/paths.sh

